<?php
declare(strict_types=1);
function scalar(string $key,string $default):string { return isset($_GET[$key]) && is_string($_GET[$key]) ? $_GET[$key] : $default; }
function esc(string $s):string { return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function number(string $key,int $default,int $min,int $max):int { return max($min,min($max,(int)scalar($key,(string)$default))); }
if (isset($_GET['source'])) {
    $index=file_get_contents(__DIR__.'/index.php');
    if(preg_match('~href="(https://[^"]+/2006/03/free-place-to-host-php-scripts-ning\.html)"~',$index,$m)) {header('Location: '.html_entity_decode($m[1]),true,302);exit;}
    http_response_code(404);exit('Source link unavailable.');
}
$name=trim(implode('',array_slice(preg_split('//u',scalar('name','Moon of Small Wonders'),-1,PREG_SPLIT_NO_EMPTY) ?: [],0,32))) ?: 'Unnamed Moon';
$seed=number('seed',2046,1,999999); $craters=number('craters',24,5,60); $tint=number('tint',35,0,360);
$phase=number('phase',0,0,85);
$texture='';
function atlas(string $name,int $seed,int $craters,int $tint,int $phase,string $texture):string {
    $n=0;
    $rand=function(int $lo,int $hi) use($seed,&$n):int {return $lo+(hexdec(substr(hash('sha256',$seed.':'.($n++)),0,7))%($hi-$lo+1));};
    $shapes='';$sites=[];
    for($i=0;$i<$craters;$i++){
        $angle=$rand(0,6283)/1000;$dist=sqrt($rand(0,10000)/10000)*228;
        $x=round(400+cos($angle)*$dist,2);$y=round(366+sin($angle)*$dist,2);$r=$rand(5,25);
        $shapes.='<g><circle cx="'.$x.'" cy="'.$y.'" r="'.$r.'" fill="#182b32" fill-opacity=".24" stroke="#fff0cf" stroke-opacity=".6" stroke-width="2"/><ellipse cx="'.($x+2).'" cy="'.($y+2).'" rx="'.($r*.68).'" ry="'.($r*.55).'" fill="#14252c" fill-opacity=".25"/></g>';
        if($i<5)$sites[]=[$x,$y,$i+1];
    }
    $markers='';foreach($sites as [$x,$y,$i])$markers.='<g><circle cx="'.$x.'" cy="'.$y.'" r="12" fill="#ffdc8b" stroke="#172b33"/><text x="'.$x.'" y="'.($y+4).'" text-anchor="middle" fill="#172b33" font-size="12" font-family="monospace">'.$i.'</text></g>';
    $xmlns='http:'.'//www.w3.org/2000/svg';
    return '<svg xmlns="'.$xmlns.'" width="800" height="900" viewBox="0 0 800 900" role="img" aria-label="Imaginary atlas of '.esc($name).'"><defs><clipPath id="disc"><circle cx="400" cy="366" r="255"/></clipPath><radialGradient id="shade" cx="32%" cy="28%"><stop offset="0" stop-color="#fff" stop-opacity=".1"/><stop offset=".65" stop-opacity="0"/><stop offset="1" stop-color="#031820" stop-opacity=".8"/></radialGradient></defs><rect width="800" height="900" fill="#10272e"/><rect x="22" y="22" width="756" height="856" fill="none" stroke="#aeaa89" stroke-opacity=".55"/><g fill="none" stroke="#a9b3a1" stroke-opacity=".35"><circle cx="400" cy="366" r="280"/><path d="M80 366H720M400 50V682" stroke-dasharray="3 9"/><circle cx="400" cy="366" r="270"/></g><g clip-path="url(#disc)"><image href="data:image/webp;base64,'.$texture.'" x="145" y="111" width="510" height="510"/><circle cx="400" cy="366" r="255" fill="hsl('.$tint.',60%,50%)" fill-opacity=".27"/>'.$shapes.'<circle cx="400" cy="366" r="255" fill="url(#shade)"/>'.($phase?'<ellipse cx="'.(650-$phase*3.5).'" cy="366" rx="255" ry="280" fill="#071b24" fill-opacity=".86"/>':'').'</g>'.$markers.'<g font-family="Georgia,serif" text-anchor="middle" fill="#f3e6c7"><text x="400" y="78" font-size="14" letter-spacing="5">POCKET MOON OBSERVATORY</text><text x="400" y="726" font-size="30">'.esc($name).'</text><text x="400" y="766" font-size="15" letter-spacing="2">SURVEY '.$seed.' · '.$craters.' IMPACT BASINS</text><text x="400" y="823" font-size="13" fill="#b5bba8">An imaginary world. A very real little PHP script.</text></g></svg>';
}
$svg=atlas($name,$seed,$craters,$tint,$phase,$texture);
if(isset($_GET['render'])){header('Content-Type: image/svg+xml; charset=UTF-8');header('X-Content-Type-Options: nosniff');if(isset($_GET['download']))header('Content-Disposition: attachment; filename="pocket-moon-'.$seed.'.svg"');echo $svg;exit;}
$params=['name'=>$name,'seed'=>$seed,'craters'=>$craters,'tint'=>$tint,'phase'=>$phase];
$q=http_build_query($params);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pocket Moon Foundry</title><style>
:root{--ink:#183037;--cream:#f4ebd6;--gold:#ce7a31;--muted:#58635d}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:Palatino,"Book Antiqua",Georgia,serif;background-image:repeating-linear-gradient(0deg,transparent 0 5px,#18303703 5px 6px)}a{color:inherit;text-underline-offset:4px}button,input{font:inherit}button,.action{cursor:pointer;touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #ca6b24;outline-offset:4px}header,main,footer{max-width:1280px;margin:auto;padding:26px 5%}header{display:flex;justify-content:space-between;border-bottom:1px solid #18303740;font:12px "Courier New",monospace;letter-spacing:1px;gap:12px}h1{font-weight:400;font-size:clamp(52px,7vw,96px);line-height:.96;letter-spacing:-4px;margin:24px 0}h1 em{color:#a65326;font-weight:400}.eyebrow{font:12px "Courier New",monospace;letter-spacing:2px;text-transform:uppercase}.intro{font-size:19px;line-height:1.55;max-width:530px}.layout{display:grid;grid-template-columns:.85fr 1.15fr;gap:7%;align-items:start}.workshop{padding-top:26px}form{border-top:2px solid var(--ink);margin-top:30px;padding-top:20px}label{display:block;font-size:16px;margin-top:22px}label:first-child{margin-top:0}input[type=text],input[type=number]{display:block;width:100%;padding:13px 10px;border:0;border-bottom:1px solid #18303770;background:#fff8e7;color:var(--ink);margin-top:9px;border-radius:0}input[type=range]{display:block;width:100%;accent-color:#ab5728;margin:16px 0;height:24px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px}output{font:13px "Courier New",monospace}.controls{display:grid;grid-template-columns:1fr 1fr;gap:18px}.primary{width:100%;background:var(--ink);color:var(--cream);border:0;padding:18px;margin-top:24px;font-size:18px}.primary:hover{background:#31545b}.secondary{background:transparent;border:1px solid #18303770;color:var(--ink);padding:12px 16px;font-size:15px}.sheet{position:sticky;top:20px;padding-top:22px}.sheet img{display:block;width:100%;box-shadow:9px 12px 0 #18303718;animation:arrive .65s ease-out}.sheet .row{margin-top:24px;flex-wrap:wrap}.action{font:14px "Courier New",monospace}.note{font-size:14px;line-height:1.55;color:var(--muted)}.field{margin-top:35px;border-top:1px solid #18303750;padding-top:18px}.field h2{font-weight:400;font-size:27px;margin:8px 0}.sites{display:flex;gap:6px;flex-wrap:wrap;margin:16px 0}.sites button{min-height:44px;min-width:44px;background:transparent;border:1px solid #18303780;border-radius:50%;color:var(--ink)}.sites button[aria-pressed=true]{background:var(--ink);color:var(--cream)}#siteNote{min-height:64px;font-size:17px;line-height:1.5}details{margin-top:30px;border-top:1px solid #18303740;padding-top:18px;line-height:1.6}summary{cursor:pointer}code,pre{font:12px "Courier New",monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e6dcc4;padding:14px}footer{font-size:14px;line-height:1.7;border-top:1px solid #18303740;margin-top:36px;padding-bottom:40px}.status{font:12px "Courier New",monospace;min-height:20px}@keyframes arrive{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@media(max-width:750px){.layout{grid-template-columns:1fr;gap:12px}.sheet{position:static;grid-row:2}.workshop{padding-top:0}h1{letter-spacing:-2px}.intro{font-size:18px}header{font-size:10px}main{padding-top:10px}.sheet img{max-height:none}footer{margin-top:10px}.controls{gap:12px}}@media(prefers-reduced-motion:reduce){.sheet img{animation:none}}@media print{header,.workshop,footer,.sheet .row,.note{display:none}.layout{display:block}.sheet{padding:0;position:static}body,main{background:white;padding:0}.sheet img{height:95vh;width:auto;max-width:100%;margin:auto;box-shadow:none}}
</style></head><body><header><a href="./">CHLOE READS JON</a><span>EST. 2006 / EXPERIMENT No. 2046</span></header><main><div class="layout"><section class="workshop"><p class="eyebrow">A small script. An entire world.</p><h1>Pocket Moon<br><em>Foundry.</em></h1><p class="intro">Somewhere, a moon is missing its cartographer. Give it a name, scatter a few craters, and bring back an atlas from a place that never existed.</p>
<form action="pocket-moon-foundry.php" method="get"><label for="name">01 / Name your discovery</label><input id="name" name="name" type="text" maxlength="32" value="<?=esc($name)?>" required>
<div class="controls"><label for="seed">Survey seed<input id="seed" name="seed" type="number" min="1" max="999999" value="<?=$seed?>" required></label><label for="craters">Impact basins <output id="cratersOut"><?=$craters?></output><input id="craters" name="craters" type="range" min="5" max="60" value="<?=$craters?>"></label></div>
<label for="tint" class="row"><span>02 / Mineral tint</span><output id="tintOut"><?=$tint?>°</output></label><input id="tint" name="tint" type="range" min="0" max="360" value="<?=$tint?>">
<label for="phase" class="row"><span>03 / Encroaching night</span><output id="phaseOut"><?=$phase?>%</output></label><input id="phase" name="phase" type="range" min="0" max="85" value="<?=$phase?>">
<p class="note">Controls take effect when you mint. The same seed always places the same craters. Night is a playful shadow, not an astronomical phase model.</p><button class="primary" type="submit">Mint my moon ↗</button></form>
<section class="field"><p class="eyebrow">Field notebook / five landing sites</p><h2>Where shall we land?</h2><div class="sites" aria-label="Choose a numbered atlas site"><?php for($i=1;$i<=5;$i++):?><button type="button" data-site="<?=$i?>" aria-pressed="false" aria-label="Explore landing site <?=$i?>"><?=$i?></button><?php endfor;?></div><p id="siteNote" aria-live="polite">Choose a numbered survey marker. Every expedition deserves one wildly unnecessary discovery.</p></section>
<details><summary>The little-script idea behind this moon</summary><p>In 2006, Jon wrote about a free place to experiment with one-off PHP scripts. This is one: your form sends a few values to PHP, which draws a repeatable crater map and returns a complete SVG atlas. No account, no installation. Just a small idea with its own address.</p><pre><?=esc('?'.$q)?></pre><p>Try changing only the seed. Then change only the crater count. The earliest craters stay put as the map fills in.</p><p>The underlying terrain is original GPT Image artwork; PHP adds your survey, tint, shadow, and numbered landing sites.</p></details></section>
<section class="sheet" aria-label="Your moon atlas"><img id="atlas" src="pocket-moon-foundry.php?<?=esc($q)?>&amp;render=1" width="800" height="900" alt="Illustrated atlas of <?=esc($name)?> with five numbered landing sites"><div class="row"><a class="action" href="pocket-moon-foundry.php?<?=esc($q)?>&amp;render=1&amp;download=1">↓ Save atlas (SVG)</a><button id="surprise" class="secondary" type="button">Discover another</button></div><p class="note">Save this page’s address to return to exactly this world. The downloaded atlas includes its artwork and can be opened or printed on its own.</p><p id="status" class="status" aria-live="polite"></p></section></div></main><footer>Inspired by Jon’s <a href="pocket-moon-foundry.php?source=1">Free place to host PHP scripts: Ning</a>.<br>A tiny tribute to the pleasure of making things just to see what happens.</footer><script>
const form=document.querySelector('form');
for(const key of ['craters','tint','phase']){const el=document.getElementById(key);el.addEventListener('input',()=>document.getElementById(key+'Out').textContent=el.value+(key==='tint'?'°':key==='phase'?'%':''));}
document.getElementById('surprise').addEventListener('click',()=>{const a=new Uint32Array(1);crypto.getRandomValues(a);document.getElementById('seed').value=a[0]%999999+1;form.requestSubmit();});
const notes=['The Sea of Misplaced Socks: strangely quiet, except for one tiny tumble dryer.','The Biscuit Escarpment: a promising ridge. Do not remove your helmet for a taste test.','The Crater of Excellent Echoes: say something kind. It comes back twice as nice.','The Library of Dust: every footprint is a sentence nobody has written before.','The Faraway Picnic Ground: low gravity, high sandwich ambitions.'];
document.querySelectorAll('[data-site]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-site]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('siteNote').textContent=notes[Number(b.dataset.site)-1];}));
document.getElementById('atlas').addEventListener('error',()=>{document.getElementById('status').textContent='The atlas could not load. Please mint your moon again.';});
</script></body></html>
